import{_ as n,o as e,c as i,a2 as r}from"./chunks/framework.DBU8LMUS.js";const h=JSON.parse('{"title":"Sistem Referral","description":"","frontmatter":{"title":"Sistem Referral","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/referral.md","filePath":"latest/referral.md","lastUpdated":1786334463000}'),t={name:"latest/referral.md"};function l(s,a,m,u,o,d){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="sistem-referral" tabindex="-1">Sistem Referral <a class="header-anchor" href="#sistem-referral" aria-label="Permalink to &quot;Sistem Referral&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p><strong>Sistem Referral</strong> memungkinkan alumni meminta rekomendasi (referensi) kepada alumni lain yang bekerja di perusahaan tujuan. Sistem ini menjaga privasi: permintaan referral hanya dapat dilihat oleh <strong>pengaju</strong> dan <strong>alumni yang dituju</strong>.</p><h2 id="mengajukan-permintaan-referral" tabindex="-1">Mengajukan Permintaan Referral <a class="header-anchor" href="#mengajukan-permintaan-referral" aria-label="Permalink to &quot;Mengajukan Permintaan Referral&quot;">​</a></h2><h3 id="membuka-formulir" tabindex="-1">Membuka Formulir <a class="header-anchor" href="#membuka-formulir" aria-label="Permalink to &quot;Membuka Formulir&quot;">​</a></h3><ol><li>Pastikan Anda sudah masuk.</li><li>Klik menu <strong>Referral</strong> atau tombol <strong>Ajukan Referral</strong>.</li><li>Anda akan diarahkan ke halaman pengajuan referral.</li></ol><h3 id="mengisi-formulir" tabindex="-1">Mengisi Formulir <a class="header-anchor" href="#mengisi-formulir" aria-label="Permalink to &quot;Mengisi Formulir&quot;">​</a></h3><p>Isi informasi berikut:</p><ul><li><strong>Alumni tujuan</strong>: pilih alumni yang bekerja di perusahaan target.</li><li><strong>Perusahaan tujuan</strong>: nama perusahaan yang Anda tuju.</li><li><strong>Posisi yang dilamar</strong> (jika sudah ada).</li><li><strong>Pesan singkat</strong> kepada alumni tujuan.</li></ul><h3 id="mengirim-permintaan" tabindex="-1">Mengirim Permintaan <a class="header-anchor" href="#mengirim-permintaan" aria-label="Permalink to &quot;Mengirim Permintaan&quot;">​</a></h3><ol><li>Klik tombol <strong>Kirim</strong>.</li><li>Permintaan tersimpan dengan status <strong>Pending</strong>.</li><li>Hanya Anda (sebagai pengaju) dan alumni tujuan yang dapat melihat permintaan ini.</li></ol><h2 id="meninjau-permintaan-masuk" tabindex="-1">Meninjau Permintaan Masuk <a class="header-anchor" href="#meninjau-permintaan-masuk" aria-label="Permalink to &quot;Meninjau Permintaan Masuk&quot;">​</a></h2><h3 id="melihat-permintaan" tabindex="-1">Melihat Permintaan <a class="header-anchor" href="#melihat-permintaan" aria-label="Permalink to &quot;Melihat Permintaan&quot;">​</a></h3><ol><li>Masuk ke akun Anda.</li><li>Buka halaman <strong>Referral</strong>.</li><li>Bagian permintaan masuk menampilkan permintaan yang ditujukan kepada Anda.</li></ol><h3 id="menanggapi-permintaan" tabindex="-1">Menanggapi Permintaan <a class="header-anchor" href="#menanggapi-permintaan" aria-label="Permalink to &quot;Menanggapi Permintaan&quot;">​</a></h3><ol><li>Buka detail permintaan.</li><li>Pilih tindakan: <ul><li><strong>Terima</strong>: Anda bersedia memberikan rekomendasi.</li><li><strong>Tolak</strong>: Anda tidak dapat membantu.</li></ul></li><li>Tulis catatan atau rekomendasi Anda jika diperlukan.</li><li>Klik <strong>Simpan</strong>.</li></ol><h2 id="status-permintaan-referral" tabindex="-1">Status Permintaan Referral <a class="header-anchor" href="#status-permintaan-referral" aria-label="Permalink to &quot;Status Permintaan Referral&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Pending</strong></td><td>Permintaan dikirim dan menunggu tanggapan alumni tujuan.</td></tr><tr><td><strong>Diterima</strong></td><td>Alumni tujuan menyetujui permintaan; proses rekomendasi berjalan.</td></tr><tr><td><strong>Ditolak</strong></td><td>Alumni tujuan tidak dapat memberikan rekomendasi.</td></tr><tr><td><strong>Selesai</strong></td><td>Proses rekomendasi telah selesai.</td></tr></tbody></table><h2 id="riwayat-permintaan" tabindex="-1">Riwayat Permintaan <a class="header-anchor" href="#riwayat-permintaan" aria-label="Permalink to &quot;Riwayat Permintaan&quot;">​</a></h2><p>Halaman <strong>Referral</strong> menampilkan riwayat permintaan yang Anda ajukan beserta statusnya. Gunakan riwayat ini untuk memantau perkembangan permintaan.</p><h2 id="privasi-dan-keamanan" tabindex="-1">Privasi dan Keamanan <a class="header-anchor" href="#privasi-dan-keamanan" aria-label="Permalink to &quot;Privasi dan Keamanan&quot;">​</a></h2><ul><li>Permintaan referral <strong>tidak ditampilkan</strong> kepada pengguna lain selain pengaju dan alumni tujuan.</li><li>Admin dapat melihat laporan konten, namun permintaan referral tetap dilindungi oleh kebijakan privasi sistem.</li><li>Jangan membagikan informasi pribadi sensitif di dalam pesan referral; komunikasikan detail melalui kanal lain setelah permintaan diterima.</li></ul><h2 id="tips-mengajukan-referral" tabindex="-1">Tips Mengajukan Referral <a class="header-anchor" href="#tips-mengajukan-referral" aria-label="Permalink to &quot;Tips Mengajukan Referral&quot;">​</a></h2><ul><li>Pilih alumni yang benar-benar mengenal Anda atau pernah bekerja sama.</li><li>Jelaskan posisi yang dilamar dan kaitannya dengan pengalaman Anda.</li><li>Sertakan pesan yang sopan dan profesional.</li></ul><p>Lanjutkan ke <a href="/webapps/latest/grup">Komunitas &amp; Grup</a> untuk bergabung dalam forum diskusi.</p>',25)])])}const p=n(t,[["render",l]]);export{h as __pageData,p as default};
